import { describe, expect, it } from 'vitest';
import { PUZZLE_NAME_ADJECTIVES, PUZZLE_NAME_NOUNS, generatePuzzleName } from './puzzle-name';

// Story 14-S3 — the new-puzzle dialog's generated default name.
//
// `generatePuzzleName(random)` builds "Adjective Noun Noun" from the
// module's own hand-picked lists, with two different nouns, using only the
// random source it's given. Each list holds at least 80 unique single
// title-case words. Do not edit this file to match an implementation.

/** A small deterministic random source (mulberry32). */
function seeded(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const WORD = /^[A-Z][a-z]+$/;

describe('14-S3 generated puzzle names', () => {
  it('each list has at least 80 unique single title-case words', () => {
    for (const [label, list] of [
      ['adjectives', PUZZLE_NAME_ADJECTIVES],
      ['nouns', PUZZLE_NAME_NOUNS],
    ] as const) {
      expect(list.length, label).toBeGreaterThanOrEqual(80);
      expect(new Set(list).size, `${label} unique`).toBe(list.length);
      for (const word of list) expect(word, label).toMatch(WORD);
    }
  });

  it('builds Adjective Noun Noun from the lists, with different nouns, within the title limit', () => {
    const random = seeded(14);
    for (let i = 0; i < 2000; i++) {
      const name = generatePuzzleName(random);
      const words = name.split(' ');
      expect(words, name).toHaveLength(3);
      expect(PUZZLE_NAME_ADJECTIVES, name).toContain(words[0]);
      expect(PUZZLE_NAME_NOUNS, name).toContain(words[1]);
      expect(PUZZLE_NAME_NOUNS, name).toContain(words[2]);
      expect(words[1], name).not.toBe(words[2]);
      expect(name.length, name).toBeLessThanOrEqual(80);
    }
  });

  it('keeps the nouns different even when the random source repeats itself', () => {
    for (const value of [0, 0.5, 0.999999]) {
      const words = generatePuzzleName(() => value).split(' ');
      expect(words, String(value)).toHaveLength(3);
      expect(words[1], String(value)).not.toBe(words[2]);
    }
  });

  it('is determined by its random source', () => {
    const a = seeded(3);
    const b = seeded(3);
    for (let i = 0; i < 20; i++) expect(generatePuzzleName(a)).toBe(generatePuzzleName(b));
  });

  it('varies: many draws give many different names', () => {
    const random = seeded(99);
    const names = new Set(Array.from({ length: 200 }, () => generatePuzzleName(random)));
    expect(names.size).toBeGreaterThan(190);
  });
});
